R16,R32,CT=2,0,68
K,N=2048,5120
class Algo(C.Structure): _fields_=[("d",C.c_uint64*8)]
class HR(C.Structure): _fields_=[("algo",Algo),("ws",C.c_size_t),("state",C.c_int),("waves",C.c_float),("res",C.c_int*4)]
h=vp(); assert L.cublasLtCreate(C.byref(h))==0
def mk(M):
    op=vp(); L.cublasLtMatmulDescCreate(C.byref(op),CT,R32)
    for a,v in ((3,1),(4,0)):
        x=C.c_int(v); L.cublasLtMatmulDescSetAttribute(op,a,C.byref(x),4)
    ls=[]
    for r,c,ld in ((K,N,K),(K,M,K),(N,M,N)):
        l=vp(); L.cublasLtMatrixLayoutCreate(C.byref(l),R16,C.c_uint64(r),C.c_uint64(c),C.c_int64(ld)); ls.append(l)
    return op,ls
def capv(algo,cap,n=4096):
    buf=(C.c_uint32*n)(); w=C.c_size_t(0)
    st=L.cublasLtMatmulAlgoCapGetAttribute(C.byref(algo),cap,buf,n*4,C.byref(w))
    return st,list(buf[:w.value//4])
def ids():
    out=(C.c_int*256)(); n=C.c_int(0)
    L.cublasLtMatmulAlgoGetIds(h,CT,R32,R16,R16,R16,R16,256,out,C.byref(n)); return list(out[:n.value])
