    x=C.c_uint32(v); return L.cublasLtMatmulAlgoConfigSetAttribute(C.byref(a),attr,C.byref(x),4)
def check(op,ls,a):
    r=HR(); st=L.cublasLtMatmulAlgoCheck(h,op,ls[0],ls[1],ls[2],ls[2],C.byref(a),C.byref(r)); return st,r
